function sabotagePage(){const c=state.covert||{};const targets=state.target_board||[];const formula='damage = bounded system disruption × success probability × covert technology';const rows=targets.map(t=>'<tr><td><strong>'+esc(t.name)+'</strong></td><td>'+esc(t.race)+'</td><td>#'+esc(t.rank)+'</td><td>'+fmt(t.defense)+'</td><td>'+fmt(t.covert)+'</td><td><span class="badge '+(t.status==='PROTECTED'?'':'good')+'">'+esc(t.status)+'</span></td><td><button class="button sabotage-intent" data-target="'+t.id+'" data-action="covert:sabotage" '+(t.status==='PROTECTED'?'disabled':'')+'>Sabotage</button></td></tr>').join('');const selected=targets.find(t=>t.status==='OPEN')||targets[0]||{id:0,name:'No target',covert:0,status:'PROTECTED'};const detection=Math.max(0,(Number(selected.covert)||0)-20-(Number(c.covert_level)||1));const success=Math.max(5,Math.min(95,100-detection));const damage=Math.max(1,Math.min(25,Math.round((Number(c.available_agents)||0)*0.10*(success/100)*(Number(c.covert_level)||1))));document.getElementById('section').textContent='ATTACK';document.getElementById('title').textContent='Sabotage Operations';document.getElementById('description').textContent='Target enemy systems with bounded sabotage damage and detection handling. '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COVERT OPERATIONS</div><h2>Sabotage mission</h2><div class="metric-grid"><div class="metric"><span>Available agents</span><strong>'+fmt(c.available_agents||0)+'</strong><small>Commander covert pool</small></div><div class="metric"><span>Detection formula</span><strong>− agents</strong><small>'+esc(formula.replace('damage = ','detection = defender counter-intelligence − attacker agents − covert technology; damage = '))+'</small></div><div class="metric"><span>Mission state</span><strong>'+esc(c.mission_state||'READY')+'</strong><small>Target and ownership validation required</small></div></div><div class="row"><span>Target intelligence</span><strong>Defense, resources, technology</strong></div><div class="row"><span>Detection handling</span><span class="badge">CLASSIFIED REPORT</span></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Buttons and forms</h2><div class="actions"><div class="action"><div><strong>Run reconnaissance</strong><small>Generate low-risk target intelligence with detection calculation.</small></div><button class="button sabotage-intent" data-action="covert:recon" data-target="'+selected.id+'">Run reconnaissance</button></div><div class="action"><div><strong>Run spy mission</strong><small>Resolve spy mission and store report.</small></div><button class="button sabotage-intent" data-action="covert:spy" data-target="'+selected.id+'">Run spy mission</button></div><div class="action"><div><strong>Run sabotage</strong><small>Resolve sabotage with detection and damage caps.</small></div><button class="button dark sabotage-intent" data-action="covert:sabotage" data-target="'+selected.id+'" '+(selected.status==='PROTECTED'?'disabled':'')+'>Run sabotage</button></div></div><p class="permission">Authenticated commander · agents required · target ownership validated</p><div id="sabotage-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">TARGET SYSTEMS</div><h2>Known enemy systems</h2><table class="table"><thead><tr><th>Realm</th><th>Race</th><th>Rank</th><th>Defense</th><th>Counter-intelligence</th><th>Status</th><th>Operation</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SABOTAGE PREVIEW</div><h2>Bounded damage model</h2><div class="metric-grid"><div class="metric"><span>Selected target</span><strong>'+esc(selected.name)+'</strong><small>'+esc(selected.status)+'</small></div><div class="metric"><span>Detection score</span><strong>'+fmt(detection)+'</strong><small>Defender covert − agents − technology</small></div><div class="metric"><span>Success probability</span><strong>'+fmt(success)+'%</strong><small>Clamped server-side</small></div><div class="metric"><span>Damage cap</span><strong>'+fmt(damage)+'</strong><small>Bounded system disruption</small></div></div><div class="row"><span>Formula</span><span class="badge good">'+esc(formula)+'</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">'+esc(formula)+'</p>'+['target_realms','players','player_resources','protection_states','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">All mutations require authentication, CSRF, RBAC, ownership, protection, resource, cooldown, and transaction checks.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.sabotage-intent').forEach(b=>b.onclick=()=>{const f=document.getElementById('sabotage-feedback');if(f){f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → target validation → detection and damage cap → CSRF/RBAC → transactional covert service.'}})}
